INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (8, 'junior_fltrp', 'wy8B', 'U1', 'So much is done for you', 'Every morning, before you wake up, a lot of work is already done for you. The bread on your table is baked during the night. Milk is brought to the shops by trucks while the streets are still empty. The roads are cleaned, and the buses are checked before the day begins.

In a modern city, thousands of jobs are done quietly so that life runs smoothly. Fruit is picked on faraway farms and is sent to markets in your town. Water is made clean before it reaches your home. Even the news you read is written and printed hours before breakfast.

Machines help with much of this work. In some factories, cars are built by robots. In many shops, prices are checked by computers, not by people.

Life is also changing fast. Soon, more work will be done by machines. Some letters will be delivered by small planes. A few cars will be driven without a driver. New energy will be made from the sun and the wind, and less coal will be burned.

Next time you enjoy a quiet morning, think of all the hidden work behind it. So much is done for you, and even more will be done in the years to come.', '城市如何运转(被动·现在/将来)', 207, 0, '[{"q": "When is the bread on your table baked?", "answer": "B", "options": ["In the early morning.", "During the night.", "After breakfast.", "By the buses."], "explanation": "''The bread ... is baked during the night''。"}, {"q": "How are the cars built in some factories?", "answer": "C", "options": ["By drivers.", "By computers.", "By robots.", "By farmers."], "explanation": "''cars are built by robots''。"}, {"q": "What is the passage mainly about?", "answer": "C", "options": ["How to bake bread at night.", "Why machines are dangerous.", "How much unseen work is done for people in a city.", "Where fruit is grown."], "explanation": "全文讲城市里大量被动完成的隐形工作。"}, {"q": "We can learn from the last part that in the future ____.", "answer": "A", "options": ["even more work will be done by machines", "people will stop using energy", "no bread will be baked", "cities will become quiet"], "explanation": "结尾''even more will be done ... by machines''可推断。"}, {"q": "In the passage, ''hidden work'' means work that is ____.", "answer": "A", "options": ["not easily seen but still done for us", "done only by hand", "never finished", "paid a lot of money"], "explanation": "由全文''隐形完成''可推断 hidden=看不见的。"}]'::jsonb, '[{"word": "baked", "cn": "烘烤(bake的过去分词)"}, {"word": "smoothly", "cn": "顺利地"}, {"word": "robot", "cn": "机器人"}, {"word": "coal", "cn": "煤"}, {"word": "delivered", "cn": "投递(deliver的过去分词)"}]'::jsonb);
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (8, 'junior_fltrp', 'wy8B', 'U1', 'How a book is made', 'Have you ever wondered how a book is made? A lot of work is done before a story reaches your hands. First, the words are written by a writer, and the pictures are drawn by an artist. Then the pages are printed by big machines. After that, the pages are folded and sewn together, and a cover is added to keep them safe. When one book is finished, it looks clean and new. At last, the books are packed into boxes and sent to bookshops all over the country. Some are even sent abroad by plane. When a book is bought and read at home, its long journey is finished. Next time you open a new book, think of all the people who helped to make it.', '书是怎么做的(被动·现在)', 127, 1, '[{"q": "Who draws the pictures for a book?", "answer": "B", "options": ["A writer.", "An artist.", "A machine.", "A reader."], "explanation": "''the pictures are drawn by an artist''。"}, {"q": "What is added to keep the pages safe?", "answer": "A", "options": ["A cover.", "A box.", "A machine.", "A picture."], "explanation": "''a cover is added to keep them safe''。"}, {"q": "What is the passage mainly about?", "answer": "C", "options": ["Why books are expensive.", "How to write a good story.", "How a book is made before it reaches readers.", "Where to buy books."], "explanation": "全文讲书如何被制作(被动)。"}]'::jsonb, '[{"word": "folded", "cn": "折叠(fold的过去分词)"}, {"word": "sewn", "cn": "缝(sew的过去分词)"}, {"word": "cover", "cn": "封面"}, {"word": "bookshop", "cn": "书店"}]'::jsonb);
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (8, 'junior_fltrp', 'wy8B', 'U1', 'How rubbish is recycled', 'Every day, a lot of rubbish is thrown away. But not all of it is wasted. At a recycling centre, the rubbish is first sorted into groups. Paper, glass, metal and plastic are put into different bins. Then each kind is cleaned and washed with care. Old glass bottles are melted and made into new ones. Used paper is turned into fresh paper again, and metal is melted and used to make new things. In this way, many old things are reused instead of thrown away. When rubbish is recycled, less is buried in the ground, and our planet is kept cleaner. These small actions are needed by everyone, because a clean world is shared by us all.', '垃圾怎样被回收(被动·现在)', 118, 1, '[{"q": "What happens to old glass bottles?", "answer": "D", "options": ["They are buried.", "They are burned.", "They are thrown into the river.", "They are melted and made into new ones."], "explanation": "''Old glass bottles are melted and made into new ones''。"}, {"q": "How is the rubbish first dealt with at the centre?", "answer": "C", "options": ["It is sold to shops.", "It is sent abroad.", "It is sorted into groups.", "It is left in bins."], "explanation": "''the rubbish is first sorted into groups''。"}, {"q": "What is the main idea of the passage?", "answer": "D", "options": ["Rubbish is always wasted.", "Glass is the best material.", "Bins are hard to find.", "Recycling helps keep our planet cleaner."], "explanation": "全文讲回收让地球更干净。"}]'::jsonb, '[{"word": "recycled", "cn": "回收(recycle的过去分词)"}, {"word": "sorted", "cn": "分类(sort的过去分词)"}, {"word": "melted", "cn": "熔化(melt的过去分词)"}, {"word": "reused", "cn": "再利用(reuse的过去分词)"}]'::jsonb);
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (8, 'junior_fltrp', 'wy8B', 'U1', 'How our school lunch is made', 'At our school, lunch is made fresh every day, and a lot of care is put into it. Early in the morning, vegetables and rice are brought to the kitchen. The vegetables are washed and cut by the cooks. Soup is cooked in big pots, and rice is steamed until it is soft. By twelve o''clock, the food is put onto plates and served in the canteen. Warm meals are enjoyed by hundreds of hungry students. After lunch, the plates are washed and the floor is cleaned. Nothing good is wasted; the food that is left is shared with the school garden. In this quiet way, a warm meal is prepared for us all before the bell rings.', '学校午餐怎样准备(被动·现在)', 119, 1, '[{"q": "Who washes and cuts the vegetables?", "answer": "B", "options": ["The students.", "The cooks.", "The teachers.", "The drivers."], "explanation": "''The vegetables are washed and cut by the cooks''。"}, {"q": "What happens to the food that is left?", "answer": "A", "options": ["It is shared with the school garden.", "It is thrown away.", "It is sold.", "It is kept for the next day."], "explanation": "''the food that is left is shared with the school garden''。"}, {"q": "What is the passage mainly about?", "answer": "D", "options": ["Why students like rice.", "How to grow vegetables.", "When the canteen opens.", "How the school lunch is prepared each day."], "explanation": "全文讲午餐如何被准备(被动)。"}]'::jsonb, '[{"word": "kitchen", "cn": "厨房"}, {"word": "cooks", "cn": "厨师(复数)"}, {"word": "canteen", "cn": "食堂"}, {"word": "served", "cn": "供应(serve的过去分词)"}]'::jsonb);
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (8, 'junior_fltrp', 'wy8B', 'U1', 'Homes of the future', 'In the future, our homes will be run in cleaner ways. Today, much power is made by burning coal, and the air is often dirty. But soon, sunlight and wind will be used to make most of our power. Solar panels will be put on every roof, and the light of the sun will be turned into power. On windy days, energy will be made by tall wind turbines. Extra power will be kept in batteries, so that it can be used on dark nights. Less coal will be burned, and cleaner air will be shared by all. Our homes will be kept warm and bright, and the planet will be protected at the same time. A greener life will be built by us, step by step.', '未来的家怎样供能(被动·将来)', 127, 1, '[{"q": "Where will solar panels be put?", "answer": "C", "options": ["In the ground.", "Inside batteries.", "On every roof.", "Under the sea."], "explanation": "''Solar panels will be put on every roof''。"}, {"q": "How will energy be made on windy days?", "answer": "A", "options": ["By tall wind turbines.", "By burning coal.", "By solar panels.", "By batteries."], "explanation": "''energy will be made by tall wind turbines''。"}, {"q": "What is the main idea of the passage?", "answer": "B", "options": ["Coal is the best energy.", "In the future, homes will use cleaner energy.", "Batteries are dangerous.", "The sun is too weak to use."], "explanation": "全文讲未来家用更清洁能源(被动将来)。"}]'::jsonb, '[{"word": "solar panels", "cn": "太阳能板"}, {"word": "roof", "cn": "屋顶"}, {"word": "turbines", "cn": "涡轮机"}, {"word": "batteries", "cn": "电池"}]'::jsonb);
-- U2 精读
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (8, 'junior_fltrp', 'wy8B', 'U2', 'The library that was saved', 'Years ago, a small library stood at the corner of our street. It was built long ago by the people of the town. Its walls were made of grey stone, and its doors were painted a warm red. As a child, I was often taken there by my grandmother.

One winter, everyone heard sad news: the old library would close. A new shopping centre was planned for that corner, and the little library was no longer needed. Many books were packed into boxes, and the reading room was left cold and empty. The children who read there were sad, and the old librarian was often seen standing quietly at the locked door.

But the people of the town were not happy. A meeting was held, and hundreds of letters were written to the government. Photos of the library were shared online, and its story was told again and again. Slowly, the whole town was moved by these voices.

In the end, the plan was changed. The library was saved, and money was raised to repair it. The old stone walls were cleaned, and new lights were put in. On the day it opened again, the streets were filled with happy people. Music was played, and fresh flowers were placed on every window.

That library was not just a building. It was loved by everyone, and it was kept alive by the people who cared.', '社区守护(被动·过去)', 234, 0, '[{"q": "What were the walls of the old library made of?", "answer": "B", "options": ["Warm red wood.", "Grey stone.", "Old boxes.", "Bright glass."], "explanation": "''Its walls were made of grey stone''。"}, {"q": "What did the people of the town do to save the library?", "answer": "C", "options": ["They built a shopping centre.", "They packed the books away.", "They held a meeting and wrote many letters.", "They closed the reading room."], "explanation": "''A meeting was held, and hundreds of letters were written''。"}, {"q": "What is the best title''s idea of the passage?", "answer": "C", "options": ["A new shopping centre in town.", "How to build a library.", "People saved their old library because they loved it.", "A cold and empty winter."], "explanation": "全文讲人们出于热爱救回老图书馆。"}, {"q": "From the passage we can infer that the townspeople ____.", "answer": "A", "options": ["cared deeply about their library", "wanted a new shopping centre", "were too busy to help", "never used the library"], "explanation": "写信、开会、分享照片可推断他们很在乎。"}, {"q": "In the passage, ''was moved by these voices'' means the town was ____.", "answer": "A", "options": ["touched and changed by what people said", "carried to a new place", "made quiet and empty", "filled with new buildings"], "explanation": "be moved=被打动;由语境可推断。"}]'::jsonb, '[{"word": "grey", "cn": "灰色的"}, {"word": "government", "cn": "政府"}, {"word": "raised", "cn": "筹集(raise的过去分词)"}, {"word": "repair", "cn": "修理"}, {"word": "packed", "cn": "打包(pack的过去分词)"}]'::jsonb);
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (8, 'junior_fltrp', 'wy8B', 'U2', 'The bridge that was rebuilt', 'For a hundred years, an old stone bridge stood over the river near our village. It was built long ago by farmers, and it was used by everyone. Children were carried across it on their way to school, and heavy bags of rice were moved over it to the market. One summer, a big flood came, and part of the bridge was broken by the rushing water. The village was cut in two, and everyone was worried. But the bridge was not forgotten. Money was raised, and new stones were carried to the river. Old and young worked together, and the bridge was slowly rebuilt by many hands. When it was opened again, it was crossed with joy by the whole village.', '被重建的老石桥(被动·过去)', 122, 1, '[{"q": "What broke part of the old bridge?", "answer": "C", "options": ["A strong wind.", "A heavy truck.", "A big flood.", "A fire."], "explanation": "''part of the bridge was broken by the rushing water''(洪水)。"}, {"q": "How was the bridge rebuilt?", "answer": "D", "options": ["By one rich man.", "By the government alone.", "By a big machine.", "By many hands working together."], "explanation": "''the bridge was slowly rebuilt by many hands''。"}, {"q": "What is the passage mainly about?", "answer": "A", "options": ["How a village rebuilt its old bridge together.", "Why floods are dangerous.", "How to carry rice to a market.", "Where the river begins."], "explanation": "全文讲村子齐心重建老桥(被动过去)。"}]'::jsonb, '[{"word": "flood", "cn": "洪水"}, {"word": "rushing", "cn": "奔涌的"}, {"word": "rebuilt", "cn": "重建(rebuild的过去分词)"}, {"word": "crossed", "cn": "穿过(cross的过去分词)"}]'::jsonb);
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (8, 'junior_fltrp', 'wy8B', 'U2', 'A photo that was found', 'Last winter, an old photo was found by me in a drawer at home. It was covered with dust, but the faces on it were still clear. In the photo, a young woman was smiling under a tree. ''Who is she?'' I asked. ''That is your grandmother,'' my mother said softly. ''The photo was taken on her wedding day, sixty years ago.'' I looked at it for a long time. The photo was kept in an old box, and it was almost forgotten. That evening, it was placed in a warm wooden frame by my mother, and it was hung on the wall. Now, when we walk past it, my grandmother''s young smile is seen by all of us again.', '被找到的老照片(被动·过去)', 121, 1, '[{"q": "When was the photo taken?", "answer": "B", "options": ["Last winter.", "On the grandmother''s wedding day.", "Yesterday.", "At a school party."], "explanation": "''The photo was taken on her wedding day, sixty years ago''。"}, {"q": "What was done with the photo that evening?", "answer": "C", "options": ["It was thrown away.", "It was sold.", "It was placed in a frame and hung on the wall.", "It was sent abroad."], "explanation": "''it was placed in a warm wooden frame ... hung on the wall''。"}, {"q": "What is the main idea of the passage?", "answer": "D", "options": ["How to clean a drawer.", "Why photos turn old.", "Where grandmother lived.", "An old family photo was found and given a new place at home."], "explanation": "全文讲找到老照片并重新珍藏(被动过去)。"}]'::jsonb, '[{"word": "drawer", "cn": "抽屉"}, {"word": "dust", "cn": "灰尘"}, {"word": "wedding", "cn": "婚礼"}, {"word": "frame", "cn": "相框"}]'::jsonb);
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (8, 'junior_fltrp', 'wy8B', 'U2', 'The apple tree grandpa planted', 'Behind our house grows a tall apple tree. It was planted by my grandpa many years ago, when my father was still a small boy. Every spring, the tree was covered with white flowers, and every autumn, sweet apples were picked by the whole family. As a child, my father was lifted up to reach the highest fruit. Cool shade was given by the tree on hot summer days, and many happy hours were spent under it. My grandpa is gone now, but the tree is still cared for by us. Its apples are shared with our neighbours, and its story is told to every child in the family. A tree was planted, and a warm memory was grown with it.', '爷爷种的苹果树(被动·过去)', 121, 1, '[{"q": "Who planted the apple tree?", "answer": "B", "options": ["The writer''s father.", "The writer''s grandpa.", "A neighbour.", "A farmer."], "explanation": "''It was planted by my grandpa many years ago''。"}, {"q": "What happened every autumn?", "answer": "A", "options": ["Sweet apples were picked by the family.", "The tree was cut down.", "White flowers came out.", "The tree was moved."], "explanation": "''every autumn, sweet apples were picked by the whole family''。"}, {"q": "What is the passage mainly about?", "answer": "C", "options": ["How to grow apples for money.", "Why summer is hot.", "A family tree that carries warm memories.", "Where grandpa was born."], "explanation": "全文借苹果树讲家族温情(被动过去)。"}]'::jsonb, '[{"word": "lifted", "cn": "举起(lift的过去分词)"}, {"word": "shade", "cn": "树荫"}, {"word": "picked", "cn": "采摘(pick的过去分词)"}, {"word": "neighbours", "cn": "邻居"}]'::jsonb);
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (8, 'junior_fltrp', 'wy8B', 'U2', 'How our lantern festival was started', 'Every year, a bright lantern festival is held in our town. But few people know how it was started. Long ago, one cold winter, the town was covered with heavy snow, and many roads were closed. People were kept inside their homes, and everyone felt sad and afraid. Then a kind old man had an idea. Red lanterns were made by hand and were lit outside every door. Warm light was shared along the dark streets, and neighbours were brought together again. Soon, songs were sung and sweet food was shared. From that winter on, the festival was held every year. Today, the streets are still filled with warm light, and the kind old story is remembered and loved by all.', '灯笼节是怎样开始的(被动·过去)', 121, 1, '[{"q": "Why did people feel sad that winter long ago?", "answer": "A", "options": ["Heavy snow closed the roads and kept them inside.", "The festival was too loud.", "The lanterns were too dear.", "The town had no food at all."], "explanation": "''the town was covered with heavy snow ... People were kept inside''。"}, {"q": "What did the old man do?", "answer": "B", "options": ["He built a new road.", "He made red lanterns and lit them outside every door.", "He left the town.", "He sold warm food."], "explanation": "''Red lanterns were made by hand and were lit outside every door''。"}, {"q": "What is the passage mainly about?", "answer": "D", "options": ["Why snow is dangerous.", "How to make a lantern.", "Where the old man lived.", "How a warm town festival was started long ago."], "explanation": "全文讲灯笼节的由来(被动过去)。"}]'::jsonb, '[{"word": "lantern", "cn": "灯笼"}, {"word": "festival", "cn": "节日"}, {"word": "lit", "cn": "点亮(light的过去分词)"}, {"word": "neighbours", "cn": "邻居"}]'::jsonb);
-- U3 精读
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (8, 'junior_fltrp', 'wy8B', 'U3', 'Reaching the top together', 'Climbing a high mountain is never easy, and no one can do it alone. Last summer, our team of six set out to reach the top of a tall, snowy mountain. Before we started, our leader told us the rules. ''On this mountain, we must stay together,'' he said. ''You must never walk alone, and you have to follow the rope at all times.''

The first days were hard. The air was thin, and we could not walk fast. Some of us felt weak and wanted to give up. But a team can do more than one person can. When someone was tired, another would carry his bag. When the path was steep, we pulled each other up with the rope.

High on the mountain, the weather can change in minutes. One afternoon, dark clouds came, and our leader shouted, ''We have to stop! It might snow tonight. We must build our tents now.'' We could do nothing but wait. All night the cold wind blew. Nobody could sleep well, and our food was almost gone. Still, no one wanted to turn back; giving up was simply not a choice for our team.

The next morning was clear. Step by step, we climbed the last part. At noon, we reached the top at last. From up there, we could see for miles. We learnt an important lesson: alone you may be strong, but together you can be far stronger.', '团队与登山(情态动词一)', 239, 0, '[{"q": "What rule did the leader give before they started?", "answer": "B", "options": ["They could walk alone if they were fast.", "They must stay together and follow the rope.", "They had to reach the top in one day.", "They should carry no bags."], "explanation": "''we must stay together ... follow the rope''。"}, {"q": "Why did the team have to stop one afternoon?", "answer": "C", "options": ["Because they reached the top.", "Because someone was lost.", "Because dark clouds came and it might snow.", "Because the rope was broken."], "explanation": "''dark clouds came ... It might snow tonight. We must build our tents''。"}, {"q": "What lesson did the team learn?", "answer": "C", "options": ["Mountains are too dangerous to climb.", "One strong person is enough.", "Working together makes people far stronger.", "Summer is the best time to climb."], "explanation": "结尾''together you can be far stronger''。"}, {"q": "We can infer that the writer''s team succeeded mainly because they ____.", "answer": "A", "options": ["helped each other and followed the rules", "climbed as fast as they could", "each walked alone", "had very good weather"], "explanation": "互相帮助、守规则可推断成功靠团队。"}, {"q": "In the passage, ''the air was thin'' means there was ____.", "answer": "A", "options": ["less oxygen high on the mountain", "a lot of dust in the air", "a cold strong wind", "thick white cloud"], "explanation": "高山空气稀薄=氧气少,由 could not walk fast 可推断。"}]'::jsonb, '[{"word": "rope", "cn": "绳索"}, {"word": "steep", "cn": "陡峭的"}, {"word": "tent", "cn": "帐篷"}, {"word": "thin", "cn": "(空气)稀薄的"}, {"word": "blew", "cn": "吹(blow的过去式)"}]'::jsonb);
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (8, 'junior_fltrp', 'wy8B', 'U3', 'Rules at the swimming pool', 'Our school has a lovely swimming pool, but before you jump in, you must know the rules. First, you have to take a shower before you swim. You must never run beside the pool, because the floor can be wet and you may fall. Young children can only swim in the shallow end, and they must stay where a coach can see them. You mustn''t push your friends into the water; it is not funny and it can be dangerous. If you feel tired, you should rest at once. When the whistle is blown, everyone has to leave the water at once. These rules may seem strict, but they keep us safe. Follow them, and everyone can enjoy a happy time in the water.', '游泳池的规则(情态·义务/许可)', 125, 1, '[{"q": "What must you do before you swim?", "answer": "C", "options": ["Run beside the pool.", "Push your friends.", "Take a shower.", "Blow the whistle."], "explanation": "''you have to take a shower before you swim''。"}, {"q": "Where can young children swim?", "answer": "B", "options": ["In the deep end.", "Only in the shallow end where a coach can see them.", "Anywhere they like.", "Outside the pool."], "explanation": "''Young children can only swim in the shallow end''。"}, {"q": "What is the passage mainly about?", "answer": "A", "options": ["The rules that keep swimmers safe.", "Why swimming is hard.", "How to build a pool.", "When the pool opens."], "explanation": "全文讲泳池安全规则(情态)。"}]'::jsonb, '[{"word": "pool", "cn": "泳池"}, {"word": "shower", "cn": "淋浴"}, {"word": "shallow", "cn": "浅的"}, {"word": "whistle", "cn": "哨子"}]'::jsonb);
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (8, 'junior_fltrp', 'wy8B', 'U3', 'Being a good group leader', 'In class, we often work in small groups, and each group must have a leader. But being a good leader is not easy. A leader should listen to everyone, because good ideas can come from anyone. You mustn''t do all the work yourself; instead, you have to share the tasks in a fair way. When a group member finds a job hard, a leader can help, or can ask a stronger student to help. A leader should stay calm, even when things go wrong. You must never laugh at a wrong answer. When people feel safe, they can do their best. A good leader helps a whole group win together, and that is a skill we can all learn.', '怎样当好组长(情态·能力/义务)', 120, 1, '[{"q": "What should a good leader do with the tasks?", "answer": "D", "options": ["Do all of them alone.", "Give them to the teacher.", "Leave them undone.", "Share them in a fair way."], "explanation": "''you have to share the tasks in a fair way''。"}, {"q": "What must a leader never do?", "answer": "A", "options": ["Laugh at a wrong answer.", "Listen to others.", "Stay calm.", "Help a weak member."], "explanation": "''You must never laugh at a wrong answer''。"}, {"q": "What is the passage mainly about?", "answer": "C", "options": ["Why groups are boring.", "How to win a game.", "How to be a good group leader.", "When to work alone."], "explanation": "全文讲如何当好组长(情态)。"}]'::jsonb, '[{"word": "leader", "cn": "组长;领导者"}, {"word": "fair", "cn": "公平的"}, {"word": "tasks", "cn": "任务"}, {"word": "calm", "cn": "冷静的"}]'::jsonb);
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (8, 'junior_fltrp', 'wy8B', 'U3', 'Joining the school band', 'Do you love music? Then you may join our school band! Everyone can come, and you don''t have to be the best player. You may choose the drum, the guitar or the violin. But if you join, you must come to practice every week. You have to bring your own music book, and you should be on time. During practice, you mustn''t play when the teacher is speaking, because everyone needs to listen. If you can''t play a part well, don''t worry; you can learn it little by little. At the end of the year, a big show is put on, and every member can play on the stage. Music is more fun when it is shared, so come and join us!', '加入学校乐队(情态·许可/义务)', 126, 1, '[{"q": "What must you do if you join the band?", "answer": "D", "options": ["Be the best player.", "Buy a new violin.", "Play alone at home.", "Come to practice every week."], "explanation": "''if you join, you must come to practice every week''。"}, {"q": "What mustn''t you do during practice?", "answer": "B", "options": ["Bring a music book.", "Play when the teacher is speaking.", "Be on time.", "Listen to others."], "explanation": "''you mustn''t play when the teacher is speaking''。"}, {"q": "What is the passage mainly about?", "answer": "D", "options": ["Why the violin is hard.", "How to write music.", "Where the show is held.", "Joining the school band and its rules."], "explanation": "全文讲加入乐队及规则(情态)。"}]'::jsonb, '[{"word": "band", "cn": "乐队"}, {"word": "drum", "cn": "鼓"}, {"word": "guitar", "cn": "吉他"}, {"word": "violin", "cn": "小提琴"}]'::jsonb);
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (8, 'junior_fltrp', 'wy8B', 'U3', 'In the school library', 'The school library is a quiet place where everyone can read and learn. To keep it nice, we all have to follow a few simple rules. You must speak softly, because loud voices can trouble others. You mustn''t eat or drink inside, because food can make the books dirty. You may borrow three books at a time, but you have to bring them back in two weeks. If you lose a book, you should pay for it. You can ask the librarian for help; she can always find the right book for you. When you finish, you must put the chairs back in place. A library is shared by everyone, so everyone must care for it too.', '图书馆的规矩(情态·义务/许可)', 118, 1, '[{"q": "How many books may you borrow at a time?", "answer": "A", "options": ["Three.", "One.", "Five.", "Ten."], "explanation": "''You may borrow three books at a time''。"}, {"q": "Why mustn''t you eat inside the library?", "answer": "C", "options": ["Because it is too dark.", "Because food is not allowed to be bought.", "Because food can make the books dirty.", "Because the librarian is hungry."], "explanation": "''You mustn''t eat or drink inside, because food can make the books dirty''。"}, {"q": "What is the passage mainly about?", "answer": "B", "options": ["Why reading is hard.", "The rules that keep the library nice for all.", "How to become a librarian.", "When the library closes."], "explanation": "全文讲图书馆规则(情态)。"}]'::jsonb, '[{"word": "library", "cn": "图书馆"}, {"word": "borrow", "cn": "借"}, {"word": "librarian", "cn": "图书管理员"}, {"word": "voices", "cn": "说话声"}]'::jsonb);
-- U4 精读
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (8, 'junior_fltrp', 'wy8B', 'U4', 'The light in the old house', 'For years, the old house at the end of our village stood empty. No one lived there, and its windows were always dark. So one autumn night, when a light appeared in an upstairs room, the whole village began to wonder.

''Someone must be inside,'' said old Mr Chen. ''A light can''t turn itself on.''

''But it can''t be a thief,'' said my mother. ''A thief would keep the house dark, not bright.''

''It may be a traveller,'' said my father. ''Or it might be some children playing a game.''

For three nights the light came and went. Some people were a little afraid; others were only curious. ''The person can''t be dangerous,'' I said to myself. ''Nothing was stolen, and no one was hurt.''

At last, a few of us walked up to the house. The door was open. Inside, by the warm light of a small lamp, sat an old man. He was thin and tired, and his clothes were worn. ''I used to live here as a boy,'' he said softly. ''I had nowhere else to go.''

The village was quiet for a moment. Then my mother spoke. ''You shouldn''t be alone on a cold night. You should come and stay with us.'' And so he did. Sometimes the answer to a mystery is much kinder than we fear. From that night on, the old man was never alone again. Warm meals were brought to his door, and the empty house slowly became a real home.', '推理与善意(情态动词二·推测)', 253, 0, '[{"q": "Why did old Mr Chen think someone was inside?", "answer": "B", "options": ["Because he saw the old man.", "Because a light can''t turn itself on.", "Because a thief was caught.", "Because children were playing."], "explanation": "''A light can''t turn itself on''→一定有人。"}, {"q": "Who was really in the old house?", "answer": "C", "options": ["A dangerous thief.", "A young traveller.", "An old man who used to live there.", "Some children playing a game."], "explanation": "''sat an old man ... I used to live here as a boy''。"}, {"q": "What is the main idea of the passage?", "answer": "D", "options": ["Old houses are dangerous places.", "Thieves often hide in empty houses.", "Children should not play at night.", "A village''s fear turned into kindness."], "explanation": "全文由猜疑转为对孤老的善意。"}, {"q": "We can infer that the villagers were ____ at the end.", "answer": "A", "options": ["kind and ready to help the old man", "angry with the old man", "still afraid of the light", "sorry they came"], "explanation": "母亲请他同住可推断村民善良。"}, {"q": "When the writer says the person ''can''t be dangerous'', he means it is ____.", "answer": "A", "options": ["impossible that the person is dangerous", "certain that the person is a thief", "possible that something was stolen", "clear that someone was hurt"], "explanation": "can''t be=不可能是,表否定推测。"}]'::jsonb, '[{"word": "upstairs", "cn": "楼上的"}, {"word": "thief", "cn": "小偷"}, {"word": "traveller", "cn": "旅行者"}, {"word": "curious", "cn": "好奇的"}, {"word": "worn", "cn": "破旧的(wear的过去分词)"}]'::jsonb);
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (8, 'junior_fltrp', 'wy8B', 'U4', 'Whose umbrella is this?', 'After the rain stopped, a red umbrella was left behind in our classroom. ''Whose can it be?'' asked Lily. ''It must belong to a girl,'' said Ben, ''because of its bright colour.'' ''It might be Anna''s,'' I said. ''She sat by the window today.'' ''It can''t be Anna''s,'' said Lily. ''Hers is blue, not red.'' We looked at the umbrella again. ''It could be a teacher''s,'' said Ben. Just then, Kate ran in. ''Oh, there it is! It must be mine,'' she said with a smile. ''I left it here this morning.'' We were happy that the umbrella found its owner. Sometimes a little thinking and a little help can solve a small mystery.', '这是谁的伞?(情态·推测)', 118, 1, '[{"q": "Why did Ben think the umbrella belonged to a girl?", "answer": "C", "options": ["Because it was wet.", "Because it was new.", "Because of its bright colour.", "Because it was small."], "explanation": "''It must belong to a girl, because of its bright colour''。"}, {"q": "Why can''t the umbrella be Anna''s?", "answer": "D", "options": ["Anna went home.", "Anna has no umbrella.", "Anna sat by the door.", "Anna''s umbrella is blue, not red."], "explanation": "''It can''t be Anna''s. Hers is blue, not red''。"}, {"q": "What is the passage mainly about?", "answer": "A", "options": ["How students guessed whose umbrella it was.", "Why it rained all day.", "How to buy an umbrella.", "Where Kate sat."], "explanation": "全文讲用推测找伞的主人(情态推测)。"}]'::jsonb, '[{"word": "umbrella", "cn": "雨伞"}, {"word": "belong", "cn": "属于"}, {"word": "owner", "cn": "物主"}, {"word": "mystery", "cn": "谜"}]'::jsonb);
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (8, 'junior_fltrp', 'wy8B', 'U4', 'A sound in the night', 'One night, I woke up and heard a strange sound outside. ''What could it be?'' I thought. ''It might be a thief,'' I said to myself, and my heart beat fast. But then I thought again. ''It can''t be a thief. A thief would be quiet, not noisy.'' The sound came again, soft and light. ''It may be the wind,'' I thought, ''or it could be a cat on the roof.'' I picked up a small torch and looked out of the window. There, on the branch of a tree, sat a big grey cat. So it was only a cat, playing quietly in the dark! I laughed at my own fear and went back to bed. Some sounds in the night are not as scary as they seem.', '夜里的声音(情态·推测)', 130, 1, '[{"q": "Why did the writer think it couldn''t be a thief?", "answer": "B", "options": ["A thief would be at school.", "A thief would be quiet, not noisy.", "A thief has no torch.", "A thief likes cats."], "explanation": "''It can''t be a thief. A thief would be quiet, not noisy''。"}, {"q": "What was really making the sound?", "answer": "A", "options": ["A grey cat on a branch.", "A thief.", "The wind only.", "A bird in the room."], "explanation": "''sat a big grey cat ... So it was only a cat, playing quietly in the dark''。"}, {"q": "What is the passage mainly about?", "answer": "C", "options": ["Why cats are dangerous.", "How to catch a thief.", "How the writer guessed and found the cause of a night sound.", "Where the tree grew."], "explanation": "全文讲用推测找出夜声原因(情态推测)。"}]'::jsonb, '[{"word": "torch", "cn": "手电筒"}, {"word": "branch", "cn": "树枝"}, {"word": "beat", "cn": "跳动(此处指心跳)"}, {"word": "scary", "cn": "吓人的"}]'::jsonb);
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (8, 'junior_fltrp', 'wy8B', 'U4', 'The lost dog', 'On my way home, I found a small brown dog sitting alone near the park gate. ''You must be far from home,'' I said softly. The dog had a collar, so it might belong to someone close by. ''Your owner could be looking for you right now,'' I thought. I could not leave it there, so I took it home. My mother said, ''It can''t be a wild dog; it is too clean and friendly.'' The next day, we put up a poster near the park. Soon a girl called us. ''That must be my dog!'' she cried. When she came, the dog ran to her at once, and its tail wagged with joy. They clearly belonged together. A little care brought them home.', '走失的小狗(情态·推测)', 125, 1, '[{"q": "Why did the writer think the dog had an owner?", "answer": "D", "options": ["It was very big.", "It could run fast.", "It was hungry.", "It had a collar."], "explanation": "''The dog had a collar, so it might belong to someone''。"}, {"q": "How did they find the owner?", "answer": "B", "options": ["They kept the dog secret.", "They put up a poster near the park.", "They took it to school.", "They sold the dog."], "explanation": "''we put up a poster near the park. Soon a girl called us''。"}, {"q": "What is the passage mainly about?", "answer": "A", "options": ["How a lost dog was helped back to its owner.", "Why dogs run away.", "How to train a dog.", "Where the park is."], "explanation": "全文讲帮走失小狗找主人(情态推测)。"}]'::jsonb, '[{"word": "collar", "cn": "(狗)项圈"}, {"word": "owner", "cn": "主人"}, {"word": "poster", "cn": "寻物启事;海报"}, {"word": "wagged", "cn": "摇(wag的过去式)"}]'::jsonb);
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (8, 'junior_fltrp', 'wy8B', 'U4', 'Why is the teacher late?', 'The bell rang, but our English teacher, Ms Lin, did not come in. ''That''s strange,'' said Ben. ''She is never late.'' ''She might be ill,'' said Lily. ''She looked tired yesterday.'' ''It can''t be that,'' I said. ''She would call the school if she were ill.'' ''Then she may be waiting in traffic,'' said Ben. ''The buses are slow in the rain.'' We waited quietly and kept guessing. ''She must be on her way,'' Lily said. Ten minutes later, Ms Lin came in, wet from the rain. ''Sorry, everyone,'' she said. ''My bus was very late.'' So Ben was right after all. It is fun to guess, but we should always wait for the real answer before we are sure.', '老师为什么迟到?(情态·推测)', 122, 1, '[{"q": "Why did the writer think Ms Lin was not ill?", "answer": "C", "options": ["She was young.", "She liked teaching.", "She would call the school if she were ill.", "She was never tired."], "explanation": "''It can''t be that. She would call the school if she were ill''。"}, {"q": "What was the real reason Ms Lin was late?", "answer": "D", "options": ["She was ill.", "She forgot the class.", "She went to a meeting.", "Her bus was very late."], "explanation": "''My bus was very late''。"}, {"q": "What is the passage mainly about?", "answer": "B", "options": ["Why buses are slow.", "Students guessing why their teacher was late.", "How to teach English.", "When the bell rings."], "explanation": "全文讲学生推测老师迟到原因(情态推测)。"}]'::jsonb, '[{"word": "traffic", "cn": "交通"}, {"word": "waiting", "cn": "等待"}, {"word": "guessing", "cn": "猜测"}, {"word": "wet", "cn": "湿的"}]'::jsonb);
-- U5 精读
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (8, 'junior_fltrp', 'wy8B', 'U5', 'The secrets inside amber', 'Deep in a quiet forest, millions of years ago, a drop of sticky liquid fell from an old tree. A small insect was trapped inside it. Slowly, over a very long time, the liquid grew hard and turned into amber. Today, scientists have found that this golden stone can keep tiny living things safe for millions of years.

When researchers look through a magnifier, they see that the insect looks almost alive. Every leg and every hair is still there. Sometimes a feather or a leaf is found inside too. Scientists believe that these tiny pieces can unlock many secrets of the past. No museum and no photograph can show what a single piece of amber shows so well.

People once thought that we could never know the ancient world. But amber has changed this idea. Studying it, researchers now understand that some insects have hardly changed in millions of years, while others have disappeared for ever. In one famous piece of amber, scientists once found a tiny feather from a dinosaur. They were amazed, because it showed that some dinosaurs were covered with feathers, not scales. They have also learnt that the earth was once much warmer than it is today.

Every piece of amber tells a story. It reminds us that our planet is very old, and that life has taken countless forms. Scientists hope that one day, amber will help us understand not only the past, but also the future of life on the earth.', '科学发现(宾语从句·that)', 248, 0, '[{"q": "How did the amber form long ago?", "answer": "B", "options": ["An insect painted it gold.", "A drop of sticky liquid fell and slowly grew hard.", "Scientists made it in a factory.", "A tree turned into stone."], "explanation": "''a drop of sticky liquid fell ... turned into amber''。"}, {"q": "What do scientists believe the tiny pieces in amber can do?", "answer": "C", "options": ["Make the insect alive again.", "Turn into new trees.", "Unlock many secrets of the past.", "Change the earth''s weather."], "explanation": "''these tiny pieces can unlock many secrets of the past''。"}, {"q": "What is the passage mainly about?", "answer": "C", "options": ["How to make golden stones.", "Why insects disappear.", "How amber helps scientists learn about the ancient world.", "Where old forests grow."], "explanation": "全文讲琥珀帮助科学家了解远古。"}, {"q": "From the passage, we can infer that amber is valuable to scientists because it ____.", "answer": "A", "options": ["keeps ancient life safe for study", "is made of pure gold", "can bring insects back to life", "grows on old trees today"], "explanation": "由''保存远古生物、解锁过去''可推断其研究价值。"}, {"q": "In the passage, ''countless forms'' means forms that are ____.", "answer": "A", "options": ["too many to count", "very small and weak", "made of stone", "found only in amber"], "explanation": "countless=数不清的。"}]'::jsonb, '[{"word": "amber", "cn": "琥珀"}, {"word": "insect", "cn": "昆虫"}, {"word": "sticky", "cn": "黏的"}, {"word": "magnifier", "cn": "放大镜"}, {"word": "countless", "cn": "无数的"}]'::jsonb);
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (8, 'junior_fltrp', 'wy8B', 'U5', 'Honey never goes bad', 'Did you know that honey almost never goes bad? Scientists have found that honey can stay good to eat for thousands of years. Long ago, people believed that honey was a gift from nature, and they were right in many ways. We now know that its sweetness keeps it safe, so that no bad things can grow in it. Some very old honey was once found deep in a cave, and researchers said that it was still good to eat. Bees work hard for many days to make it, and I think that we should never waste a single drop. Every time I taste honey, I remember that nature has many quiet wonders we are only just beginning to understand.', '蜂蜜为什么不会坏(宾从·that)', 120, 1, '[{"q": "How long can honey stay good, according to scientists?", "answer": "C", "options": ["A few days.", "One winter.", "Thousands of years.", "Ten hours."], "explanation": "''honey can stay good to eat for thousands of years''。"}, {"q": "What keeps honey safe?", "answer": "A", "options": ["Its sweetness, so that no bad things can grow.", "The cold air.", "The dark cave.", "The glass jar."], "explanation": "''its sweetness keeps it safe, so that no bad things can grow in it''。"}, {"q": "What is the passage mainly about?", "answer": "D", "options": ["How bees fly.", "Where caves are found.", "How to open a jar.", "Why honey almost never goes bad."], "explanation": "全文讲蜂蜜为何不坏(宾从that)。"}]'::jsonb, '[{"word": "honey", "cn": "蜂蜜"}, {"word": "cave", "cn": "洞穴"}, {"word": "sweetness", "cn": "甜味"}, {"word": "wonders", "cn": "奇迹"}]'::jsonb);
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (8, 'junior_fltrp', 'wy8B', 'U5', 'The dance of the bees', 'Have you ever thought that bees can talk to each other? Of course, they do not use words. Scientists have found that bees share news by dancing. When one bee finds flowers full of sweet nectar, it flies back to the hive and dances in the air. The other bees watch, and they know that food is near. The dance even shows which way to fly and how far to go. Long ago, people thought that bees were simple little things. But now we understand that they are clever and work as a team. Because of this dance, the whole hive is fed, and no bee is left hungry. I believe that we can still learn a lot from these small teachers of the sky.', '会跳舞的蜜蜂(宾从·that)', 125, 1, '[{"q": "How do bees share news, according to scientists?", "answer": "B", "options": ["By singing.", "By dancing.", "By writing.", "By calling."], "explanation": "''bees share news by dancing''。"}, {"q": "What does the dance show?", "answer": "A", "options": ["Which way to fly and how far to go.", "The colour of flowers.", "The name of a bee.", "The age of the hive."], "explanation": "''The dance even shows which way to fly and how far to go''。"}, {"q": "What is the passage mainly about?", "answer": "C", "options": ["Why flowers are sweet.", "How to keep bees.", "How clever bees share news by dancing.", "Where hives are built."], "explanation": "全文讲蜜蜂跳舞传信(宾从that)。"}]'::jsonb, '[{"word": "bees", "cn": "蜜蜂"}, {"word": "nectar", "cn": "花蜜"}, {"word": "hive", "cn": "蜂巢"}, {"word": "clever", "cn": "聪明的"}]'::jsonb);
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (8, 'junior_fltrp', 'wy8B', 'U5', 'Do trees talk?', 'Many people think that trees just stand still and do nothing. But scientists now believe that trees can help each other in quiet ways. They have found that trees are joined under the ground by their roots. Through these roots, a strong tree can share food with a weak one. When one tree feels that danger is near, it can warn the others, and they get ready. Researchers say that a forest is like a big family, where no tree lives quite alone. They even believe that older trees care for the young ones that grow around them. I used to think that a wood was only a group of trees. Now I understand that it is a living world, full of secrets we are just starting to see.', '树会交流吗(宾从·that)', 129, 1, '[{"q": "How are trees joined under the ground?", "answer": "B", "options": ["By stones.", "By their roots.", "By water pipes.", "By ropes."], "explanation": "''trees are joined under the ground by their roots''。"}, {"q": "What can a strong tree do for a weak one?", "answer": "D", "options": ["Cut it down.", "Move it away.", "Give it a name.", "Share food with it."], "explanation": "''a strong tree can share food with a weak one''。"}, {"q": "What is the passage mainly about?", "answer": "C", "options": ["Why forests are dark.", "How to plant a tree.", "How trees help each other like a family.", "Where roots grow."], "explanation": "全文讲树木互助(宾从that)。"}]'::jsonb, '[{"word": "roots", "cn": "树根"}, {"word": "warn", "cn": "警告"}, {"word": "weak", "cn": "弱的"}, {"word": "secrets", "cn": "秘密"}]'::jsonb);
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (8, 'junior_fltrp', 'wy8B', 'U5', 'Why I read every night', 'Every night before I sleep, I read for half an hour. My mother once said reading is food for the mind, and I think she is right. When I read, I feel that I can travel to faraway places without leaving my bed. I have learnt that a good book can make a sad day better. I also believe that reading helps me write and speak more clearly, because I meet many new words. Some friends say that they have no time to read. But I think that even ten minutes a night can help. Now reading has become a habit, and I know that it will stay with me for the rest of my life.', '我为什么每晚读书(宾从·that)', 118, 1, '[{"q": "What did the writer''s mother say about reading?", "answer": "D", "options": ["It is a waste of time.", "It is only for school.", "It is too hard.", "It is food for the mind."], "explanation": "''reading is food for the mind''。"}, {"q": "Why does the writer believe reading helps with writing?", "answer": "B", "options": ["Because books are cheap.", "Because the reader meets many new words.", "Because reading is fast.", "Because it is done at night."], "explanation": "''reading helps me ... because I meet many new words''。"}, {"q": "What is the passage mainly about?", "answer": "A", "options": ["Why the writer reads every night.", "How to sleep well.", "Where to buy books.", "When to do homework."], "explanation": "全文讲每晚读书的理由(宾从that)。"}]'::jsonb, '[{"word": "mind", "cn": "头脑;心智"}, {"word": "faraway", "cn": "遥远的"}, {"word": "clearly", "cn": "清楚地"}, {"word": "habit", "cn": "习惯"}]'::jsonb);
-- U6 精读
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (8, 'junior_fltrp', 'wy8B', 'U6', 'The painter of the seasons', 'In a small mountain town lived an old painter named Grandpa Wen. For fifty years, he painted the same subject: the 24 Solar Terms, the ancient Chinese way of dividing the year into seasons. Many visitors wondered why he never grew tired of it.

''People often ask me when I will paint something new,'' Grandpa Wen once said with a smile. ''But they do not always understand what these old terms mean to me.''

Long ago, farmers used the 24 Solar Terms to decide when to plant and when to rest. Grandpa Wen still remembered how his grandfather watched the sky and the fields. Each term had its own feeling. In his paintings, a boy runs after the first spring wind; an old woman rests under a green tree in the summer heat; wild geese fly south as autumn comes; a warm lamp glows on a long winter night.

Younger people did not always know whether these old terms still mattered. Grandpa Wen wanted to show them that they did. He often explained why the seasons change and how people once lived close to nature. Slowly, his simple paintings became popular, and visitors came from faraway cities. No one could say for sure how the news spread. Some visitors even asked whether they could learn to paint like him, and he always welcomed them warmly.

Before he grew very old, Grandpa Wen gave all his paintings to the town school. ''I do not know whether these children will become painters,'' he said softly. ''But I hope they will remember where their culture comes from, and why it still lives today.''', '二十四节气与艺术(宾语从句·if/whether/wh)·改写(老树真人IP→虚构画家)', 268, 0, '[{"q": "What did Grandpa Wen paint for fifty years?", "answer": "B", "options": ["Faraway cities.", "The 24 Solar Terms.", "His own grandfather.", "The town school."], "explanation": "''For fifty years, he painted the same subject: the 24 Solar Terms''。"}, {"q": "In the past, what did farmers use the 24 Solar Terms to decide?", "answer": "C", "options": ["Whether to become painters.", "How to sell paintings.", "When to plant and when to rest.", "Where to build a school."], "explanation": "''farmers used the 24 Solar Terms to decide when to plant and when to rest''。"}, {"q": "What is the passage mainly about?", "answer": "C", "options": ["How to become a famous painter.", "Why young people leave their hometown.", "An old painter who kept a piece of Chinese culture alive through art.", "How the weather changes in the mountains."], "explanation": "全文借虚构画家讲用艺术传承节气文化。"}, {"q": "Why did Grandpa Wen give his paintings to the town school?", "answer": "A", "options": ["He hoped the children would remember their culture.", "He wanted the children to sell them.", "He needed more room at home.", "He was asked to by the government."], "explanation": "结尾''I hope they will remember where their culture comes from''。"}, {"q": "In the passage, ''these old terms still mattered'' means the terms were still ____.", "answer": "A", "options": ["important and worth keeping", "difficult to paint", "known only to farmers", "used to sell things"], "explanation": "matter=要紧、有意义,由传承主题可推断。"}]'::jsonb, '[{"word": "subject", "cn": "(绘画等的)题材"}, {"word": "terms", "cn": "节气(24 Solar Terms 二十四节气)"}, {"word": "geese", "cn": "大雁(goose的复数)"}, {"word": "glows", "cn": "发出柔光"}, {"word": "culture", "cn": "文化"}]'::jsonb);
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (8, 'junior_fltrp', 'wy8B', 'U6', 'How do birds find their way?', 'Every autumn, millions of birds fly south for the winter, and every spring they come back. Have you ever wondered how they find their way? For a long time, no one knew whether birds used their eyes or something else. Now scientists are learning how these small travellers do it. They believe that birds can feel which way is north, as if they had a map inside them. Some birds also watch where the sun sets, and others follow the stars at night. Young birds learn from old ones which path to take. No one can yet say for sure how birds know so much. But every time I see them fly, I wonder what other secrets the sky still keeps.', '鸟儿如何找到路(宾从·wh/how)', 121, 1, '[{"q": "What do some birds watch to find their way?", "answer": "B", "options": ["The trees.", "Where the sun sets.", "The rivers.", "The roads."], "explanation": "''Some birds also watch where the sun sets''。"}, {"q": "How do young birds learn which path to take?", "answer": "D", "options": ["From books.", "From people.", "From the wind.", "From old birds."], "explanation": "''Young birds learn from old ones which path to take''。"}, {"q": "What is the passage mainly about?", "answer": "A", "options": ["How birds find their way when they fly south.", "Why winter is cold.", "How to keep a bird.", "Where the stars are."], "explanation": "全文讲鸟如何辨路(宾从wh)。"}]'::jsonb, '[{"word": "south", "cn": "向南"}, {"word": "travellers", "cn": "旅行者"}, {"word": "stars", "cn": "星星"}, {"word": "path", "cn": "路线"}]'::jsonb);
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (8, 'junior_fltrp', 'wy8B', 'U6', 'Why do leaves fall?', 'In autumn, the green leaves turn yellow and brown, and soon they fall to the ground. Have you ever asked yourself why this happens? As a child, I did not know whether the trees were ill. My grandpa smiled and told me how nature works. In winter, there is less light and less water, so a tree cannot feed all its leaves. To stay alive, the tree lets its leaves go and takes a long rest. The fallen leaves are not wasted; they keep the ground warm and later become food for the roots. When spring comes, we can all see how new green leaves grow again. Now I understand that falling leaves are just a part of life, not a sign of death.', '树叶为什么会落(宾从·why/whether)', 124, 1, '[{"q": "Why can''t a tree feed all its leaves in winter?", "answer": "C", "options": ["Because it is too old.", "Because birds eat them.", "Because there is less light and less water.", "Because the wind is strong."], "explanation": "''In winter, there is less light and less water, so a tree cannot feed all its leaves''。"}, {"q": "What do the fallen leaves do for the tree?", "answer": "B", "options": ["They are burned.", "They keep the ground warm and become food for the roots.", "They are sold.", "They are taken away."], "explanation": "''they keep the ground warm and later become food for the roots''。"}, {"q": "What is the passage mainly about?", "answer": "D", "options": ["Why autumn is short.", "How to draw a leaf.", "Where grandpa lived.", "Why leaves fall and how it helps the tree."], "explanation": "全文讲树叶为何落(宾从why/whether)。"}]'::jsonb, '[{"word": "leaves", "cn": "树叶(leaf的复数)"}, {"word": "rest", "cn": "休息"}, {"word": "fallen", "cn": "落下的(fall的过去分词)"}, {"word": "sign", "cn": "迹象"}]'::jsonb);
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (8, 'junior_fltrp', 'wy8B', 'U6', 'Where does a river begin?', 'When we stand by a wide river, few of us ask where it begins. For years, I did not know how such a big river starts. Last summer, my father showed me. High in the mountains, cold water comes out of the ground as a tiny spring. At first, it is so small that you can step over it. Then many little streams meet, and no one can say exactly where one ends and another begins. Slowly, the water grows wider and stronger as it flows down. My father asked me whether I knew where all this water was going. ''To the sea,'' I said. Now, when I see a great river, I remember how it once began as a single drop in the hills.', '河流从哪里开始(宾从·where/how)', 125, 1, '[{"q": "How does a big river begin high in the mountains?", "answer": "A", "options": ["As a tiny spring coming out of the ground.", "As a wide lake.", "As heavy rain.", "As melting snow only."], "explanation": "''cold water comes out of the ground as a tiny spring''。"}, {"q": "Where did the writer say all the water was going?", "answer": "C", "options": ["To a lake.", "To the fields.", "To the sea.", "To a town."], "explanation": "''To the sea, I said''。"}, {"q": "What is the passage mainly about?", "answer": "D", "options": ["Why summers are hot.", "How to swim in a river.", "When the rain comes.", "Where and how a river begins."], "explanation": "全文讲河流从何而始(宾从where/how)。"}]'::jsonb, '[{"word": "spring", "cn": "泉水"}, {"word": "streams", "cn": "溪流"}, {"word": "flows", "cn": "流动"}, {"word": "drop", "cn": "水滴"}]'::jsonb);
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (8, 'junior_fltrp', 'wy8B', 'U6', 'Can we save water?', 'Water comes to our homes so easily that we often forget how important it is. One day, our teacher asked us whether we knew how much water a family wastes each day. No one was sure. She told us how small habits can save a lot. Do you know why a running tap wastes so much? In one minute, more water runs away than you might think. So turn off the tap while you brush your teeth. Take a short shower, not a long one. When it rains, we can even keep the water in a barrel for the garden. I am not sure whether one person can change the world, but I know how good it feels to try.', '我们能省水吗(宾从·whether/how)', 120, 1, '[{"q": "What should you do while you brush your teeth?", "answer": "C", "options": ["Take a long shower.", "Leave the tap running.", "Turn off the tap.", "Fill a barrel."], "explanation": "''turn off the tap while you brush your teeth''。"}, {"q": "What can we do with rain water?", "answer": "B", "options": ["Throw it away.", "Keep it in a barrel for the garden.", "Drink it at once.", "Send it to the sea."], "explanation": "''we can even keep the water in a barrel for the garden''。"}, {"q": "What is the passage mainly about?", "answer": "A", "options": ["How small habits can save water.", "Why rain is cold.", "How to grow a garden.", "Where water comes from."], "explanation": "全文讲省水的小习惯(宾从whether/how)。"}]'::jsonb, '[{"word": "wastes", "cn": "浪费"}, {"word": "tap", "cn": "水龙头"}, {"word": "shower", "cn": "淋浴"}, {"word": "barrel", "cn": "(接雨用的)桶"}]'::jsonb);

-- 断言
DO $$
DECLARE tot int; intn int; extn int; qbad int; peru int;
BEGIN
  SELECT count(*) INTO tot FROM public.junior_reading WHERE publisher='junior_fltrp' AND volume='wy8B';
  IF tot<>30 THEN RAISE EXCEPTION 'total=% 期望30', tot; END IF;
  SELECT count(*) INTO intn FROM public.junior_reading WHERE publisher='junior_fltrp' AND volume='wy8B' AND difficulty=0;
  IF intn<>6 THEN RAISE EXCEPTION '精读(diff0)=% 期望6', intn; END IF;
  SELECT count(*) INTO extn FROM public.junior_reading WHERE publisher='junior_fltrp' AND volume='wy8B' AND difficulty=1;
  IF extn<>24 THEN RAISE EXCEPTION '泛读(diff1)=% 期望24', extn; END IF;
  SELECT count(*) INTO qbad FROM public.junior_reading WHERE publisher='junior_fltrp' AND volume='wy8B'
    AND NOT ((difficulty=0 AND jsonb_array_length(questions)=5) OR (difficulty=1 AND jsonb_array_length(questions)=3));
  IF qbad<>0 THEN RAISE EXCEPTION '题数不符(精读5/泛读3)的篇=%', qbad; END IF;
  SELECT count(*) INTO peru FROM (SELECT unit FROM public.junior_reading WHERE publisher='junior_fltrp' AND volume='wy8B' GROUP BY unit HAVING count(*)<>5) t;
  IF peru<>0 THEN RAISE EXCEPTION '每单元≠5篇(1精读+4泛读)的单元数=%', peru; END IF;
  RAISE NOTICE 'OK: wy8B 阅读 % 篇(精读6+泛读24)· 6单元各5', tot;
END $$;

COMMIT;

SELECT unit, difficulty, count(*) 篇, min(jsonb_array_length(questions))||'-'||max(jsonb_array_length(questions)) 题数 FROM public.junior_reading WHERE publisher='junior_fltrp' AND volume='wy8B' GROUP BY unit,difficulty ORDER BY unit,difficulty DESC;